            err = abi.encodeWithSelector(
                ERROR_STRING_SELECTOR,
                abi.encodePacked(WRAPPED_ERROR_PREFIX, HexUtils.bytesToHex(err))
            );
        }
        return err;
    }

    /// @dev Unwrap a typed error from `Error(string)`.
    ///      Does nothing if detection and extracton fails.
